window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[315]={"id":"315","numero":315,"titre":"Leucémies aiguës","objectifs":[{"id":"315-1","rang":"A","rubrique":"Définition","titre":"Connaître les critères définissant une leucémie aiguë (LA)","contenu":"<p>La <span class=\"kw-def\">leucémie aiguë</span> est définie par une <span class=\"kw-def\">expansion clonale</span>, dans la <span class=\"kw-def\">moelle osseuse</span>, de <span class=\"kw-def\">blastes</span> — précurseurs immatures des cellules sanguines — <strong>bloqués à un <span class=\"kw-def\">stade</span> précoce de leur <span class=\"kw-bio\">différenciation</span></strong>. Cette prolifération envahit la moelle et compromet l'<span class=\"kw-def\">hématopoïèse normale</span>.</p>\n      <p>Le <strong><span class=\"kw-def\">critère diagnostique</span> formel</strong> est cytologique : moelle riche en cellules contenant <strong><span class=\"kw-chiffre\">≥ 20 % de blastes</span></strong> au myélogramme (parfois jusqu'à <span class=\"kw-chiffre\">100 %</span>). La caractérisation complète associe l'examen morphologique, l'<span class=\"kw-bio\">immunophénotypage</span>, la <span class=\"kw-bio\">cytogénétique</span> et la <span class=\"kw-bio\">biologie moléculaire</span> des blastes.</p>\n      <p>C'est une affection <strong>rare</strong> : <span class=\"kw-chiffre\">4500 cas/an</span> en France (2018). Non traitée, elle est mortelle en quelques semaines à quelques mois.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le seuil de <span class=\"kw-chiffre\">20 %</span> de blastes s'apprécie <strong>dans la moelle</strong>, jamais dans le sang. Une LA peut exister avec peu ou pas de <span class=\"kw-clinique\">blastes circulants</span> (forme leucopénique) — le myélogramme reste indispensable.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 316 — Syndrome myélodysplasique</em></p>","frequence":0},{"id":"315-2","rang":"A","rubrique":"Définition","titre":"Connaître les catégories de LA (hors classification)","contenu":"<p>On distingue <strong>deux grandes catégories</strong> de leucémie aiguë selon la lignée hématopoïétique d'origine des blastes : la <strong><span class=\"kw-def\">LAM</span></strong> (leucémie aiguë myéloïde) et la <strong><span class=\"kw-def\">LAL</span></strong> (leucémie aiguë lymphoblastique). La distinction repose sur la morphologie, la cytochimie et l'immunophénotype des blastes.</p>\n      <table >\n        <thead><tr><th></th><th>LAM — myéloïde</th><th>LAL — lymphoblastique</th></tr></thead>\n        <tbody>\n          <tr><td>Morphologie des blastes</td><td>Blastes de <strong>grande taille</strong> ; quelques <span class=\"kw-clinique\">granulations</span> ; parfois <span class=\"kw-clinique\">bâtonnets rouges azurophiles = corps d'Auer</span></td><td>Blastes de <strong>petite/moyenne taille</strong> ; <span class=\"kw-clinique\">cytoplasme peu abondant</span> ; <span class=\"kw-clinique\">noyau à contours irréguliers</span>, <span class=\"kw-clinique\">chromatine claire</span></td></tr>\n          <tr><td>Cytochimie</td><td><span class=\"kw-bio\">Myéloperoxydase +++</span> ; <span class=\"kw-bio\">estérases positives</span> (LAM4/LAM5)</td><td><span class=\"kw-bio\">Myéloperoxydase négative</span></td></tr>\n          <tr><td>Immunophénotype</td><td><span class=\"kw-bio\">CD13</span> ; <span class=\"kw-bio\">CD33</span> ; <span class=\"kw-bio\">CD34</span></td><td>LAL-B (<span class=\"kw-chiffre\">65 %</span>) : <span class=\"kw-bio\">CD19</span>, <span class=\"kw-bio\">CD20</span>, <span class=\"kw-bio\">CD79a</span><br>LAL-T (<span class=\"kw-chiffre\">35 %</span>) : <span class=\"kw-bio\">CD3</span>, <span class=\"kw-bio\">CD5</span></td></tr>\n          <tr><td><span class=\"kw-def\">Classification</span></td><td><span class=\"kw-bio\">FAB</span>, selon le degré de <span class=\"kw-bio\">différenciation</span> (<span class=\"kw-chiffre\">M0 à M7</span>)</td><td>Immunologique (<span class=\"kw-bio\">immunophénotypage</span>), stades de LAL-B et LAL-T</td></tr>\n        </tbody>\n      </table>\n      <p>Trois <strong>formes cliniques particulières</strong> à connaître :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">LAM3</span></strong> (promyélocytaire) — <span class=\"kw-alerte\">CIVD quasi-constante</span> qui fait toute sa gravité ; translocation <span class=\"kw-bio\">t(15;17)</span> ; <span class=\"kw-alerte\">urgence</span> thérapeutique par <span class=\"kw-ttt\">ATRA</span>.</li>\n        <li><strong><span class=\"kw-def\">LAM5</span></strong> (monoblastique) — hyperleucocytaire ; atteintes extra-médullaires (méningées, cutanées, gingivales) ; risque de <span class=\"kw-alerte\">leucostase</span>.</li>\n        <li><strong><span class=\"kw-def\">LAL à chromosome Philadelphie</span></strong> — LAL-B portant la <span class=\"kw-bio\">t(9;22)</span> ; traitement par <span class=\"kw-ttt\">inhibiteur de tyrosine kinase</span> ; <span class=\"kw-def\">pronostic</span> péjoratif.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 316 — Syndrome myélodysplasique · 317 — Syndrome myéloprolifératif · 318 — Leucémie lymphoïde chronique · 319 — Lymphome malin</em></p>","frequence":0},{"id":"315-3","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des LA","contenu":"<p>La majorité des LA sont <strong>primitives</strong>, sans cause identifiée. Des <span class=\"kw-etio\">facteurs de risque</span> sont néanmoins reconnus — certains ouvrant droit à une <strong>reconnaissance en maladie professionnelle</strong>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>LAM</th><th>LAL</th></tr></thead>\n        <tbody>\n          <tr><td>Génétiques constitutionnels</td><td><span class=\"kw-etio\">Trisomie 21</span> ; <span class=\"kw-etio\">maladie de Fanconi</span> ; <span class=\"kw-etio\">mutations GATA2 / DDX41</span> ; <span class=\"kw-etio\">syndrome de Li-Fraumeni</span> ; <span class=\"kw-etio\">ataxie-télangiectasie</span></td><td><span class=\"kw-etio\">Anomalies génétiques constitutionnelles</span></td></tr>\n          <tr><td>Iatrogènes et toxiques</td><td><strong>Chimiothérapies :</strong> <span class=\"kw-etio\">agents alkylants</span> (délai <span class=\"kw-chiffre\">&lt; 5 ans</span>) ; <span class=\"kw-etio\">inhibiteurs de topo-isomérase 2</span> (délai <span class=\"kw-chiffre\">&lt; 2 ans</span>)<br><strong><span class=\"kw-etio\">Toxique</span> :</strong> <span class=\"kw-etio\">benzène</span> (<span class=\"kw-etio\">tabac</span>, carrosserie, pétrochimie)</td><td><span class=\"kw-etio\">Pesticides</span> ; <span class=\"kw-etio\">solvants</span></td></tr>\n          <tr><td>Radiations ionisantes</td><td><span class=\"kw-etio\">Radiothérapie anti-cancéreuse</span> ; <span class=\"kw-etio\">exposition professionnelle</span></td><td>—</td></tr>\n          <tr><td>Acutisation d'une hémopathie</td><td><span class=\"kw-etio\">SMP</span> ; <span class=\"kw-etio\">SMD</span></td><td><span class=\"kw-etio\">LMC</span> (à la différence des autres SMP)</td></tr>\n          <tr><td>Virus</td><td>—</td><td><span class=\"kw-etio\">HTLV1</span> (leucémie-lymphome T) ; <span class=\"kw-etio\">EBV</span> (type Burkitt) ; <span class=\"kw-etio\">VIH</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span class=\"kw-etio\">benzène</span> et les <span class=\"kw-etio\">radiations ionisantes</span> (exposition professionnelle) exposent à une <strong>reconnaissance en maladie professionnelle</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 182 — Environnement professionnel, sécurité au travail · 316 — Syndrome myélodysplasique · 317 — Syndrome myéloprolifératif</em></p>","frequence":0},{"id":"315-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques liés à l’insuffisance médullaire","contenu":"<p>L'<span class=\"kw-bio\">envahissement</span> médullaire par les blastes étouffe l'<span class=\"kw-def\">hématopoïèse normale</span> : il n'existe <strong>aucun signe caractéristique</strong>, et la symptomatologie est rapidement progressive. La présentation associe <strong>trois syndromes</strong>, traduisant les trois cytopénies.</p>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Cytopénie</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Syndrome anémique</span></td><td><span class=\"kw-bio\">Anémie</span></td><td>Installation rapide, souvent <strong>mal toléré</strong> : <span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">dyspnée</span> ; <span class=\"kw-clinique\">pâleur</span> ; <span class=\"kw-clinique\">douleur thoracique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Syndrome hémorragique</span></td><td><span class=\"kw-bio\">Thrombopénie</span></td><td>Saignements cutanéo-muqueux : <span class=\"kw-clinique\">purpura</span> ; <span class=\"kw-clinique\">ecchymoses</span> ; <span class=\"kw-clinique\">gingivorragies</span><br>La <span class=\"kw-alerte\">CIVD</span> aggrave avec des saignements viscéraux/profonds</td></tr>\n          <tr><td><span class=\"kw-clinique\">Syndrome infectieux</span></td><td><span class=\"kw-bio\">Neutropénie</span></td><td>Clinique souvent pauvre : <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-clinique\">angine ulcéro-nécrotique</span> ; <span class=\"kw-clinique\">aphtose</span> ; <span class=\"kw-clinique\">pneumopathie</span> ; <span class=\"kw-clinique\">cellulites</span> notamment périnéales</td></tr>\n        </tbody>\n      </table>\n      <p>S'y associe fréquemment un <strong><span class=\"kw-clinique\">syndrome tumoral</span></strong> par <span class=\"kw-bio\">envahissement</span> des organes lymphoïdes : <span class=\"kw-clinique\">adénopathies</span> ; <span class=\"kw-clinique\">hépato-splénomégalie</span> ; <span class=\"kw-clinique\">amygdalomégalie</span> — surtout présent dans les <span class=\"kw-def\">LAL</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":0},{"id":"315-5","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques et biologiques de gravité","contenu":"<p>Plusieurs situations transforment la LA en <strong><span class=\"kw-alerte\">urgence</span> vitale</strong> dès la prise en charge initiale. Elles relèvent soit de l'<span class=\"kw-def\">insuffisance médullaire</span>, soit de la <span class=\"kw-def\">maladie elle-même</span>.</p>\n      <table >\n        <thead><tr><th>Urgence</th><th>Mécanisme &amp; <span class=\"kw-def\">terrain</span></th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Cytopénies profondes</span></td><td><span class=\"kw-bio\">Anémie</span> <span class=\"kw-chiffre\">&lt; 7 g/dL</span> (risque de <span class=\"kw-def\">SCA</span>) ; <span class=\"kw-bio\">thrombopénie</span> <span class=\"kw-chiffre\">&lt; 20 G/L</span> (<span class=\"kw-alerte\">hémorragie rétinienne/méningée</span>) ; <span class=\"kw-bio\">neutropénie</span> <span class=\"kw-chiffre\">&lt; 0,5 G/L</span> (<span class=\"kw-def\">sepsis</span> sévère à BGN)</td><td><span class=\"kw-ttt\">Urgence transfusionnelle</span> ; <span class=\"kw-ttt\">antibiothérapie</span> en cas de neutropénie fébrile</td></tr>\n          <tr><td><span class=\"kw-alerte\">CIVD</span></td><td><span class=\"kw-def\">LAM3</span> +++ (quasi-constante) ; <span class=\"kw-def\">LAM4/LAM5</span> hyperleucocytaires</td><td>Transfusion de <span class=\"kw-bio\">plaquettes</span> + <span class=\"kw-ttt\">plasma frais congelé</span> + concentré de <span class=\"kw-bio\">fibrinogène</span> ; <span class=\"kw-ttt\">ATRA</span> dans la LAM3</td></tr>\n          <tr><td><span class=\"kw-alerte\">Syndrome de lyse tumorale</span></td><td><span class=\"kw-bio\">Hyperuricémie</span> + <span class=\"kw-bio\">hyperkaliémie</span> + <span class=\"kw-bio\">hyperphosphorémie</span> + <span class=\"kw-bio\">hypocalcémie</span> + <span class=\"kw-bio\">LDH</span> très élevés ; surtout après début de la <span class=\"kw-ttt\">chimiothérapie</span></td><td><span class=\"kw-ttt\">Hyperhydratation</span> ; <span class=\"kw-ttt\">rasburicase</span> si hyperleucocytose/forme <span class=\"kw-etio\">tumorale</span>, sinon <span class=\"kw-ttt\">allopurinol</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Syndrome de leucostase</span></td><td><span class=\"kw-def\">LAM5</span> +++ (et LAM4) ; <span class=\"kw-bio\">hyperleucocytose</span> <span class=\"kw-chiffre\">&gt; 100 G/L</span> ; atteinte capillaire pulmonaire et cérébrale</td><td><span class=\"kw-ttt\">Cytoréduction</span> urgente ; <span class=\"kw-ci\">transfusion de CGR contre-indiquée</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Compression médiastinale</span></td><td><span class=\"kw-def\">LAL-T</span> ++ (<span class=\"kw-bio\">envahissement</span> thymique) → <span class=\"kw-alerte\">syndrome cave supérieur</span> ; <span class=\"kw-alerte\">compression trachéale</span> ; <span class=\"kw-imagerie\">épanchement pleural</span></td><td>Prise en charge en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">corticothérapie</span> / <span class=\"kw-ttt\">chimiothérapie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Devant la triade <span class=\"kw-alerte\">insuffisance médullaire + blastes circulants + CIVD</span>, suspecter une <span class=\"kw-def\">LAM3 promyélocytaire</span> et débuter l'<span class=\"kw-ttt\">ATRA</span> <strong>sans attendre</strong> la confirmation cytogénétique de la t(15;17).</div>\n      <div class=\"callout callout-warn\"><strong>Pièges.</strong> Les <span class=\"kw-ci\">transfusions de CGR sont contre-indiquées</span> en cas de leucostase (elles augmentent la viscosité sanguine). Ne <strong>jamais alcaliniser les urines</strong> dans le <span class=\"kw-clinique\">syndrome de lyse</span> — risque de précipitation de cristaux de phosphate de calcium.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 215 — <span class=\"kw-def\">Purpura</span> · 329 — Transfusion sanguine</em></p>","frequence":2},{"id":"315-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir identifier les signes évocateurs du diagnostic de LA sur l’hémogramme","contenu":"<p>L'<span class=\"kw-bio\">hémogramme est toujours anormal</span> au cours d'une LA — il reflète l'insuffisance médullaire et oriente le diagnostic, mais ne le pose pas (le myélogramme reste indispensable).</p>\n      <table >\n        <thead><tr><th>Lignée</th><th>Anomalie</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td>Érythrocytaire</td><td><span class=\"kw-bio\">Anémie arégénérative</span> <span class=\"kw-bio\">normocytaire</span> ou modérément <span class=\"kw-bio\">macrocytaire</span></td><td><strong>Quasi-constante</strong>, parfois sévère</td></tr>\n          <tr><td>Plaquettaire</td><td><span class=\"kw-bio\">Thrombopénie</span>, parfois <span class=\"kw-chiffre\">&lt; 10 G/L</span></td><td>Presque constante</td></tr>\n          <tr><td>Granuleuse</td><td><span class=\"kw-bio\">Neutropénie</span>, voire <span class=\"kw-alerte\">agranulocytose</span> d'emblée</td><td>Presque constante</td></tr>\n          <tr><td>Leucocytaire</td><td><span class=\"kw-bio\">Leucocytose</span> <strong>variable</strong> : <span class=\"kw-bio\">leucopénie</span> (formes leucopéniques) <em>ou</em> <span class=\"kw-bio\">hyperleucocytose</span> majeure (formes hyperleucocytaires)</td><td>Variable</td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-clinique\">frottis sanguin</span> peut révéler des <strong><span class=\"kw-clinique\">blastes circulants</span></strong>, en proportion variable ; leur identification morphologique est parfois difficile et justifie une relecture cytologique spécialisée.</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Un <span class=\"kw-bio\">hémogramme</span> normal <span class=\"kw-alerte\">n'élimine pas</span> une LA (surtout chez l'enfant). À l'inverse, la présence de blastes dans le sang ne suffit pas : seul le <span class=\"kw-bio\">myélogramme</span> affirme le diagnostic.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":2},{"id":"315-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’intérêt diagnostique du myélogramme","contenu":"<p>La <span class=\"kw-def\">ponction/aspiration médullaire</span> (myélogramme) est <strong>systématique</strong> : c'est l'examen <strong>clé</strong> du diagnostic, indispensable même en présence de blastes circulants. Elle permet d'affirmer le diagnostic <strong>et</strong> de typer la leucémie.</p>\n      <p><strong><span class=\"kw-def\">Diagnostic positif</span></strong> : moelle souvent riche en cellules, contenant <strong><span class=\"kw-chiffre\">≥ 20 % de blastes</span></strong>.</p>\n      <table >\n        <thead><tr><th>Analyse</th><th>Apport diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td>Morphologie + cytochimie</td><td>Différencie <span class=\"kw-def\">LAL</span> / <span class=\"kw-def\">LAM</span> (mais pas LAL-T / LAL-B) ; la <span class=\"kw-bio\">myéloperoxydase</span> affirme la nature myéloïde ; <span class=\"kw-bio\">estérases</span> négatives dans la LAM3, positives dans les LAM4/LAM5</td></tr>\n          <tr><td>Immunophénotypage</td><td>Recherche les <span class=\"kw-bio\">marqueurs CD</span> membranaires/intracytoplasmiques ; confirme le caractère hématopoïétique (<span class=\"kw-bio\">CD34</span>) et la lignée ; <strong>indispensable pour classer les LAL</strong> (B <span class=\"kw-bio\">vs</span> T) ; <span class=\"kw-def\">suivi</span> de la <span class=\"kw-bio\">maladie résiduelle</span></td></tr>\n          <tr><td>Cytogénétique</td><td><span class=\"kw-bio\">Caryotype</span> (anomalies acquises dans <span class=\"kw-chiffre\">50-60 %</span>) complété par la <span class=\"kw-bio\">FISH</span> ; capitale pour le <span class=\"kw-def\">pronostic</span> et le traitement — ex. <span class=\"kw-bio\">t(15;17)</span> (LAM3), <span class=\"kw-bio\">t(9;22)</span> chromosome Philadelphie</td></tr>\n          <tr><td>Biologie moléculaire</td><td>Mutations ponctuelles non visibles en cytogénétique (<span class=\"kw-bio\">FLT3-ITD</span>, <span class=\"kw-bio\">IDH1</span>) ; <span class=\"kw-def\">pronostic</span>, cibles thérapeutiques, <span class=\"kw-bio\">maladie résiduelle</span></td></tr>\n          <tr><td>Cryoconservation</td><td>Conservation systématique de blastes et de matériel cellulaire pour analyses complémentaires</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège fréquent.</strong> Le diagnostic de LA = <span class=\"kw-chiffre\">≥ 20 %</span> de blastes <strong>dans la moelle</strong>, pas dans le sang.</div>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-bio\">biopsie ostéo-médullaire (BOM)</span> est <strong>inutile</strong>, sauf quand l'aspiration médullaire est impossible — ce qui évoque une LA avec myélofibrose (type LAM7).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 316 — Syndrome myélodysplasique</em></p>","frequence":3},{"id":"315-8","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les particularités épidémiologiques des LA de l’enfant","contenu":"<p>Les leucémies aiguës sont les <strong><span class=\"kw-def\">cancers pédiatriques les plus fréquents</span></strong> : elles représentent <strong><span class=\"kw-chiffre\">1/3</span> de l'ensemble des cancers de l'enfant</strong>. Contrairement à l'adulte — où la LAM domine — c'est la <span class=\"kw-def\">LAL</span> qui prédomine largement chez l'enfant.</p>\n      <table >\n        <thead><tr><th></th><th>LAL</th><th>LAM</th></tr></thead>\n        <tbody>\n          <tr><td>Part des LA de l'enfant</td><td><strong><span class=\"kw-chiffre\">80 %</span></strong></td><td><span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Incidence</span></td><td><span class=\"kw-chiffre\">~400 nouveaux cas/an</span> (LAL-B <span class=\"kw-chiffre\">85 %</span>, LAL-T <span class=\"kw-chiffre\">15-20 %</span>)</td><td><span class=\"kw-chiffre\">~70 nouveaux cas/an</span></td></tr>\n          <tr><td>Âge</td><td>Pic d'<span class=\"kw-def\">incidence</span> entre <span class=\"kw-chiffre\">2 et 5 ans</span> ; second pic à l'<span class=\"kw-clinique\">adolescence</span></td><td><span class=\"kw-def\">Incidence</span> maximale chez le <span class=\"kw-clinique\">nourrisson</span>, décroît jusqu'à <span class=\"kw-chiffre\">10 ans</span> puis réaugmente</td></tr>\n        </tbody>\n      </table>\n      <p>Particularité <span class=\"kw-ttt\">biologique</span> : chez l'enfant de <span class=\"kw-chiffre\">1-10 ans</span>, les LAL portent souvent une translocation <span class=\"kw-bio\">ETV6-RUNX1</span> ou une <span class=\"kw-bio\">hyperdiploïdie</span> — altérations oncogéniques initiatrices rares à l'âge adulte.</p>","frequence":0},{"id":"315-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances cliniques et biologiques devant faire évoquer une LA chez l’enfant","contenu":"<p>Chez l'enfant, la LA évolue typiquement sur <span class=\"kw-chiffre\">2 à 3 semaines</span>. Les signes sont les mêmes que chez l'adulte — <span class=\"kw-clinique\">insuffisance médullaire</span> (anémie, thrombopénie, neutropénie) et <span class=\"kw-clinique\">syndrome tumoral</span> — mais certaines atteintes sont propres à l'enfant.</p>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Présentation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Gros testicule</span></td><td>Augmentation de volume testiculaire ; <span class=\"kw-alerte\">site de rechute fréquent</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Douleurs ostéoarticulaires, boiterie</span></td><td>Enfant qui ne veut plus monter les escaliers, veut être porté, « trop sage », ne joue plus ; <span class=\"kw-imagerie\">bandes claires métaphysaires</span> en <span class=\"kw-imagerie\">radiographie</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Infiltrats extramédullaires</span></td><td>Atteintes <span class=\"kw-clinique\">chloromateuses</span>, fréquentes chez le nourrisson atteint de LAM ; peuvent mimer une tumeur solide</td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-bio\">hémogramme</span> est anormal dans la majorité des cas, mais peut être <span class=\"kw-alerte\">normal sans éliminer le diagnostic</span> : forme hyperleucocytaire à blastose variable, ou forme pancytopénique sans blaste.</p>\n      <div class=\"callout callout-warn\"><strong>Pièges pédiatriques.</strong> Devant une <span class=\"kw-clinique\">boiterie</span> ou des <span class=\"kw-clinique\">douleurs osseuses</span> de l'enfant, demander une <span class=\"kw-bio\">NFS</span> pour éliminer une LA <strong>même en l'absence de symptomatologie évocatrice</strong>. Ne pas confondre les blastes avec des <span class=\"kw-bio\">lymphocytes hyperbasophiles</span> (infections virales, très fréquentes en pédiatrie) → relecture cytologique en cas de doute.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 54 — Boiterie de l'enfant · 213 — Anémie</em></p>","frequence":1},{"id":"315-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les indications de réalisation d’un myélogramme chez l’enfant","contenu":"<p>Chez l'enfant, le <span class=\"kw-def\">myélogramme</span> <strong>confirme le diagnostic</strong> de leucémie aiguë. Ses indications sont à connaître pour ne le réaliser ni à tort ni avec retard.</p>\n      <p><strong>Indications</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Bi- ou pancytopénie</span> constatée sur l'<span class=\"kw-bio\">hémogramme</span>.</li>\n        <li><span class=\"kw-clinique\">Cytopénie isolée</span> associée à un <span class=\"kw-clinique\">syndrome tumoral</span>.</li>\n      </ul>\n      <p>Les analyses réalisées sont les <strong>mêmes que chez l'adulte</strong> : <span class=\"kw-bio\">morphologie</span>, <span class=\"kw-bio\">cytochimie</span>, <span class=\"kw-bio\">immunophénotypage</span>, <span class=\"kw-bio\">cytogénétique</span> et <span class=\"kw-bio\">biologie moléculaire</span> — la <span class=\"kw-bio\">génétique</span> constituant le principal élément pronostique des leucémies de l'enfant.</p>\n      <p>Le bilan associé comprend l'examen du <span class=\"kw-bio\">LCS</span> (recherche d'un <span class=\"kw-alerte\">envahissement neuroméningé</span>, technique de concentration Cytospin®) et le bilan du <span class=\"kw-alerte\">syndrome de lyse</span>.</p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p>Plusieurs situations transforment la LA en <span class=\"kw-alerte\">urgence vitale</span> dès la PEC initiale — qu'elles relèvent de l'<span class=\"kw-def\">insuffisance médullaire</span> ou de la <span class=\"kw-def\">maladie elle-même</span>.</p><p><strong>Cytopénies profondes</strong></p><p><span class=\"kw-ttt\">Urgence transfusionnelle</span> ; <span class=\"kw-ttt\">antibiothérapie</span> en cas de neutropénie fébrile</p><ul><li><span class=\"kw-bio\">Anémie</span> <span class=\"kw-chiffre\">&lt; 7 g/dL</span> → risque de <span class=\"kw-alerte\">syndrome coronarien aigu</span></li><li><span class=\"kw-bio\">Thrombopénie</span> <span class=\"kw-chiffre\">&lt; 20 G/L</span> → <span class=\"kw-alerte\">hémorragie rétinienne ou méningée</span></li><li><span class=\"kw-bio\">Neutropénie</span> <span class=\"kw-chiffre\">&lt; 0,5 G/L</span> → <span class=\"kw-alerte\">sepsis sévère</span> à BGN</li></ul><p><strong><span class=\"kw-alerte\">CIVD</span></strong></p><p>Transfusion de <span class=\"kw-bio\">plaquettes</span> + <span class=\"kw-ttt\">plasma frais congelé</span> + concentré de <span class=\"kw-ttt\">fibrinogène</span> ; <span class=\"kw-ttt\">ATRA</span> dans la LAM3</p><ul><li><span class=\"kw-def\">LAM3</span> +++ (quasi-constante) ; <span class=\"kw-def\">LAM4/LAM5</span> hyperleucocytaires</li><li><span class=\"kw-alerte\">Syndrome hémorragique</span> + microthromboses diffuses</li></ul><p><strong><span class=\"kw-clinique\">Syndrome de lyse</span> <span class=\"kw-etio\">tumorale</span></strong></p><p><span class=\"kw-ttt\">Hyperhydratation</span> + <span class=\"kw-ttt\">rasburicase</span> (si hyperleucocytose / forme <span class=\"kw-etio\">tumorale</span>) sinon <span class=\"kw-ttt\">allopurinol</span> ; <span class=\"kw-ci\">ne jamais alcaliniser les urines</span></p><ul><li><span class=\"kw-bio\">Hyperuricémie</span> + <span class=\"kw-bio\">hyperkaliémie</span> + <span class=\"kw-bio\">hyperphosphorémie</span> + <span class=\"kw-bio\">hypocalcémie</span> + <span class=\"kw-bio\">LDH</span> très élevés</li><li>Surtout après le début de la <span class=\"kw-ttt\">chimiothérapie</span> ; <span class=\"kw-alerte\">insuffisance rénale aiguë</span> quasi-constante</li></ul><p><strong><span class=\"kw-clinique\">Syndrome de leucostase</span></strong></p><p><span class=\"kw-ttt\">Cytoréduction</span> urgente ; <span class=\"kw-ci\">transfusion de CGR contre-indiquée</span> (augmente la viscosité)</p><ul><li><span class=\"kw-def\">LAM5</span> +++ (et LAM4) ; <span class=\"kw-bio\">hyperleucocytose</span> <span class=\"kw-chiffre\">&gt; 100 G/L</span></li><li>Atteinte capillaire <span class=\"kw-clinique\">pulmonaire</span> (hypoxie réfractaire) et <span class=\"kw-clinique\">cérébrale</span> (troubles de conscience, <span class=\"kw-alerte\">convulsions</span>)</li></ul><p><strong>Compression médiastinale</strong></p><p>PEC en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">corticothérapie</span> / <span class=\"kw-ttt\">chimiothérapie</span></p><ul><li><span class=\"kw-def\">LAL-T</span> ++ (<span class=\"kw-bio\">envahissement</span> thymique) → <span class=\"kw-alerte\">syndrome cave supérieur</span>, <span class=\"kw-alerte\">compression trachéale</span>, <span class=\"kw-imagerie\">épanchement pleural</span></li></ul>","principes":"<p>Traitement en <span class=\"kw-def\">centre spécialisé</span>, protocoles précis, en <span class=\"kw-chiffre\">2 phases</span> (induction puis consolidation, ± entretien) : il repose sur la <span class=\"kw-ttt\">chimiothérapie intensive</span> ± <span class=\"kw-ttt\">greffe de CSH</span>. La <span class=\"kw-def\">LAM3</span> est une <span class=\"kw-alerte\">urgence thérapeutique</span> par <span class=\"kw-ttt\">ATRA</span>.</p><p><strong>Phases du traitement</strong></p><ul><li><strong>Induction</strong> : <span class=\"kw-ttt\">chimiothérapie intensive</span> → <span class=\"kw-alerte\">aplasie de 3 semaines</span> ; vise la rémission complète (<span class=\"kw-chiffre\">&lt; 5 %</span> de blastes)</li><li><strong>Consolidation</strong> : réduit la <span class=\"kw-bio\">maladie résiduelle</span> (<span class=\"kw-ttt\">chimiothérapie</span>, autogreffe, <span class=\"kw-ttt\">allogreffe</span>)</li><li><strong>Entretien</strong> : surtout <span class=\"kw-def\">LAL</span> et <span class=\"kw-def\">LAM3</span> ; traitements oraux ~<span class=\"kw-chiffre\">2 ans</span></li></ul><p><strong>Moyens thérapeutiques</strong></p><ul><li><span class=\"kw-ttt\">Chimiothérapie</span> toujours en association (anthracyclines, cytarabine…)</li><li><span class=\"kw-ttt\">Thérapies ciblées</span> : <span class=\"kw-ttt\">ITK anti-ABL1</span> (chromosome Philadelphie), <span class=\"kw-ttt\">anti-FLT3</span>, <span class=\"kw-ttt\">ATRA</span> / inhibiteurs d'<span class=\"kw-bio\">IDH</span> (LAM3), <span class=\"kw-ttt\">anticorps anti-CD33 / anti-CD20</span></li><li><span class=\"kw-ttt\">Allogreffe de CSH</span> : effet anti-leucémique du greffon, mais <span class=\"kw-def\">mortalité</span> <span class=\"kw-etio\">toxique</span> → pas chez le sujet trop âgé</li><li><span class=\"kw-ttt\">Radiothérapie</span> : prophylaxie neuroméningée, <span class=\"kw-clinique\">irradiation</span> corporelle totale pré-greffe</li></ul><p><strong>LAM3 promyélocytaire <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> thérapeutique</span></strong></p><p>Traiter la <span class=\"kw-alerte\">CIVD</span> (<span class=\"kw-bio\">plaquettes</span> + PFC + <span class=\"kw-bio\">fibrinogène</span>) et le <span class=\"kw-alerte\">syndrome de lyse</span> (hyperhydratation + rasburicase)</p><ul><li>Débuter l'<span class=\"kw-ttt\">ATRA</span> sans attendre la confirmation de la <span class=\"kw-bio\">t(15;17)</span></li><li><span class=\"kw-ttt\">ATRA</span> + <span class=\"kw-ttt\">trioxyde d'arsenic</span> (ou ATRA + <span class=\"kw-ttt\">chimiothérapie</span>)</li></ul><p><strong>LAL à chromosome Philadelphie</strong></p><p><span class=\"kw-def\">Pronostic</span> péjoratif ; <span class=\"kw-ttt\">PL prophylactiques</span> systématiques dans les LAL</p><ul><li><span class=\"kw-bio\">t(9;22)</span> / BCR-ABL1 → <span class=\"kw-ttt\">inhibiteur de tyrosine kinase</span> + <span class=\"kw-ttt\">chimiothérapie</span></li></ul>","suivi":"<p><strong>Rémission complète <span class=\"q\">— objectif du traitement</span></strong></p><p>Ne correspond PAS à une éradication : la <span class=\"kw-bio\">maladie résiduelle</span> reste détectable au niveau moléculaire</p><ul><li><span class=\"kw-bio\">Hémogramme</span> : absence de blastes, <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 1 G/L</span>, <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&gt; 100 G/L</span></li><li><span class=\"kw-bio\">Myélogramme</span> : <span class=\"kw-chiffre\">&lt; 5 %</span> de blastes</li></ul><p><strong>Maladie résiduelle</strong></p><ul><li>Suivie par <span class=\"kw-bio\">immunophénotypage</span>, <span class=\"kw-bio\">PCR</span> et <span class=\"kw-bio\">cytométrie de flux</span></li></ul><p><strong>Rechutes</strong></p><p>Atteinte neuroméningée → <span class=\"kw-ttt\">PL prophylactiques</span> systématiques dans les LAL</p><ul><li>Surtout dans les <span class=\"kw-chiffre\">5 ans</span> de la rémission ; nouvelle rémission plus difficile, <span class=\"kw-def\">pronostic</span> moins bon</li><li>Médullaire ou extramédullaire (<span class=\"kw-clinique\">testiculaire</span> et <span class=\"kw-clinique\">neuroméningée</span> dans les LAL)</li></ul><p><strong>Facteurs pronostiques</strong></p><ul><li><span class=\"kw-clinique\">Âge</span> <span class=\"kw-chiffre\">&gt; 60 ans</span> (mauvais <span class=\"kw-def\">pronostic</span>), <span class=\"kw-def\">comorbidités</span>, ATCD</li><li>Maladie : <span class=\"kw-bio\">leucocytose</span>, <span class=\"kw-bio\">cytogénétique</span>, anomalies moléculaires</li><li>Réponse au traitement</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/hematologie-cancerologie/cancers","label":"Pedia-univ — Cancers"},{"href":"https://radiopaedia.org/articles/acute-myeloid-leukemia","label":"Radiopaedia : Acute myeloid leukemia"},{"href":"https://radiopaedia.org/articles/leukaemia","label":"Radiopaedia : Leukaemia"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Myélogramme : blastose médullaire ≥ 20 % ? — Examen clé du diagnostic, systématique même en présence de blastes circulants","detail":"<h4>CAT — démarche diagnostique devant une suspicion de leucémie aiguë — Confirmation par le myélogramme puis typage LAM / LAL</h4>","branches":[{"to":"t-pas-la","label":"< 20 % de blastes","color":"blue"},{"to":"q-typage","label":"≥ 20 % de blastes → LA confirmée","color":"red"}]},{"id":"t-pas-la","kind":"terminal","label":"Pas de leucémie aiguë","color":"blue","detail":"<h4>Interprétation</h4><ul><li>Le <span class=\"kw-def\">critère diagnostique</span> formel (<span class=\"kw-chiffre\">≥ 20 %</span> de blastes <strong>dans la moelle</strong>) n'est pas atteint : le diagnostic de <span class=\"kw-def\">leucémie aiguë</span> est écarté.</li></ul><h4>Diagnostics à évoquer</h4><ul><li><span class=\"kw-etio\">Syndrome myélodysplasique</span> (blastose médullaire <span class=\"kw-chiffre\">&lt; 20 %</span>)</li><li><span class=\"kw-etio\">Syndrome mononucléosique</span> : <span class=\"kw-bio\">lymphocytes hyperbasophiles</span> polymorphes (<span class=\"kw-etio\">EBV</span>), à ne pas confondre avec des blastes</li><li>Autres causes de <span class=\"kw-clinique\">cytopénies</span></li></ul><h4>Piège</h4><ul><li>La présentation initiale sur l'<span class=\"kw-bio\">hémogramme</span> peut être compatible avec une LA <strong>et</strong> un SMD → relecture cytologique.</li></ul><h4>Renvoi</h4><ul><li>Item 316 (syndrome myélodysplasique)</li></ul>"},{"id":"q-typage","kind":"decision","label":"Cytochimie (MPO) + immunophénotypage ? — Myéloperoxydase, corps d'Auer, marqueurs CD membranaires","branches":[{"to":"q-lam3","label":"MPO + / corps d'Auer → lignée myéloïde (LAM)","color":"amber"},{"to":"t-lal","label":"MPO – / marqueurs lymphoïdes (CD19, CD3) → LAL","color":"amber"}]},{"id":"q-lam3","kind":"decision","label":"Promyélocytes + corps d'Auer en fagots + t(15;17) ? — Rechercher en priorité une LAM3 promyélocytaire","branches":[{"to":"t-lam3","label":"Oui — LAM3","color":"red"},{"to":"t-lam","label":"Non — autre LAM","color":"amber"}]},{"id":"t-lam3","kind":"terminal","label":"LAM3 promyélocytaire — urgence","color":"red","detail":"<h4>Cytologie</h4><ul><li>Myélogramme : promyélocytes, <span class=\"kw-clinique\">corps d'Auer « en fagots »</span> ; <span class=\"kw-bio\">myéloperoxydase +</span>, estérases –</li></ul><h4><span class=\"kw-etio\">Génétique</span></h4><ul><li><span class=\"kw-bio\">t(15;17)</span> ; transcrit de fusion <span class=\"kw-bio\">PML-RARα</span></li></ul><h4>Gravité</h4><ul><li><span class=\"kw-alerte\">CIVD</span> quasi-constante, qui fait toute la gravité de cette forme</li></ul><h4>CAT</h4><ul><li><span class=\"kw-alerte\">Urgence</span> : débuter l'<span class=\"kw-ttt\">ATRA</span> sans attendre la confirmation cytogénétique</li><li><span class=\"kw-ttt\">ATRA</span> + <span class=\"kw-ttt\">trioxyde d'arsenic</span> (ou ATRA + <span class=\"kw-ttt\">chimiothérapie</span>)</li><li><span class=\"kw-alerte\">CIVD</span> : <span class=\"kw-ttt\">plaquettes</span> + <span class=\"kw-ttt\">PFC</span> + <span class=\"kw-ttt\">fibrinogène</span> ; lyse : <span class=\"kw-ttt\">hyperhydratation</span> + <span class=\"kw-ttt\">rasburicase</span></li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li>Bon (survie sans rechute ~<span class=\"kw-chiffre\">80 %</span> à<span class=\"kw-chiffre\"> 5 ans</span>) une fois la phase aiguë de <span class=\"kw-alerte\">CIVD</span> dépassée</li></ul>"},{"id":"t-lam","kind":"terminal","label":"Autre LAM","color":"amber","detail":"<h4>Caractérisation</h4><ul><li><span class=\"kw-bio\">Myéloperoxydase +++</span> ; estérases + dans les LAM4/LAM5 ; <span class=\"kw-bio\">CD13</span>, <span class=\"kw-bio\">CD33</span>, <span class=\"kw-bio\">CD34</span></li></ul><h4>Forme à risque</h4><ul><li><span class=\"kw-def\">LAM5</span> monoblastique : hyperleucocytaire, atteintes extra-médullaires (méningées, cutanées, gingivales), risque de <span class=\"kw-alerte\">leucostase</span></li></ul><h4>Risques</h4><ul><li><span class=\"kw-alerte\">Leucostase</span> si <span class=\"kw-bio\">hyperleucocytose</span> <span class=\"kw-chiffre\">&gt; 100 G/L</span> ; <span class=\"kw-alerte\">syndrome de lyse</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Chimiothérapie</span> (anthracyclines + cytarabine) ± <span class=\"kw-ttt\">allogreffe de CSH</span></li><li><span class=\"kw-ttt\">Thérapies ciblées</span> : <span class=\"kw-ttt\">anti-FLT3</span>, inhibiteurs d'<span class=\"kw-bio\">IDH</span>, <span class=\"kw-ttt\">anti-CD33</span></li></ul>"},{"id":"t-lal","kind":"terminal","label":"LAL — leucémie aiguë lymphoblastique","color":"amber","detail":"<h4>Immunophénotypage (indispensable)</h4><ul><li><span class=\"kw-def\">LAL-B</span> (<span class=\"kw-chiffre\">65 %</span>) : <span class=\"kw-bio\">CD19</span>, <span class=\"kw-bio\">CD20</span>, <span class=\"kw-bio\">CD79a</span> · <span class=\"kw-def\">LAL-T</span> (<span class=\"kw-chiffre\">35 %</span>) : <span class=\"kw-bio\">CD3</span>, <span class=\"kw-bio\">CD5</span></li></ul><h4><span class=\"kw-etio\">Génétique</span></h4><ul><li><span class=\"kw-bio\">t(9;22)</span> chromosome Philadelphie (LAL-B) → <span class=\"kw-ttt\">inhibiteur de tyrosine kinase</span> ; <span class=\"kw-def\">pronostic</span> péjoratif</li></ul><h4>Atteintes</h4><ul><li><span class=\"kw-clinique\">Syndrome tumoral</span> marqué ; <span class=\"kw-alerte\">masse médiastinale</span> dans la LAL-T ; <span class=\"kw-alerte\">atteinte neuroméningée</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Chimiothérapie</span> + <span class=\"kw-ttt\">ITK</span> si chromosome Philadelphie</li><li><span class=\"kw-ttt\">PL prophylactiques</span> systématiques (atteinte neuroméningée)</li></ul>"}]},"cards":[{"i":"29690ee427e0","n":315,"o":"315-1","u":"Définition","t":"Connaître les critères définissant une leucémie aiguë (LA)","q":"Quels pièges diagnostiques concernant le seuil de blastes doit-on connaître pour la leucémie aiguë ?","a":"<p>Le seuil de 20 % de blastes pour le diagnostic de leucémie aiguë s'apprécie toujours dans la <strong>moelle osseuse</strong> et non dans le sang circulant. Une leucémie aiguë peut exister avec peu ou pas de blastes circulants (forme leucopénique), rendant le myélogramme indispensable pour le diagnostic.</p>"},{"i":"781395539f4a","n":315,"o":"315-1","u":"Définition","t":"Connaître les critères définissant une leucémie aiguë (LA)","q":"Quels examens complémentaires sont nécessaires pour une caractérisation complète des blastes dans le diagnostic de la leucémie aiguë ?","a":"<p>La caractérisation complète des blastes dans une leucémie aiguë associe l'<strong>examen morphologique</strong>, l'<strong>immunophénotypage</strong>, la <strong>cytogénétique</strong> et la <strong>biologie moléculaire</strong>.</p>"},{"i":"ddebe6f81656","n":315,"o":"315-1","u":"Définition","t":"Connaître les critères définissant une leucémie aiguë (LA)","q":"Quel est le critère diagnostique formel d'une leucémie aiguë (LA) ?","a":"<p>Le critère diagnostique formel d'une leucémie aiguë est la présence de <strong>≥ 20 % de blastes</strong> au myélogramme.</p>"},{"i":"e02796002e1a","n":315,"o":"315-1","u":"Définition","t":"Connaître les critères définissant une leucémie aiguë (LA)","q":"Comment définit-on une leucémie aiguë (LA) sur le plan physiopathologique et hématologique ?","a":"<p>La leucémie aiguë (LA) est une <strong>expansion clonale</strong>, au sein de la moelle osseuse, de <strong>blastes</strong> (précurseurs immatures des cellules sanguines). Ces cellules sont bloquées à un <strong>stade précoce de leur différenciation</strong>, ce qui entraîne une prolifération envahissante de la moelle et compromet l'hématopoïèse normale.</p>"},{"i":"31c5fef6196b","n":315,"o":"315-2","u":"Définition","t":"Connaître les catégories de LA (hors classification)","q":"Quelle est la principale différence cytochimique entre les leucémies aiguës myéloïdes (LAM) et les leucémies aiguës lymphoblastiques (LAL) ?","a":"<ul><li>Les blastes de <strong>LAM</strong> sont <strong>myéloperoxydase +++</strong> et estérases positives (notamment LAM4/LAM5).</li><li>Les blastes de <strong>LAL</strong> sont <strong>myéloperoxydase négative</strong>.</li></ul>"},{"i":"367d2a83e73f","n":315,"o":"315-2","u":"Définition","t":"Connaître les catégories de LA (hors classification)","q":"Quelles sont les caractéristiques morphologiques des blastes des leucémies aiguës myéloïdes (LAM) et des leucémies aiguës lymphoblastiques (LAL) ?","a":"<ul><li>Pour les <strong>LAM</strong> : les blastes sont de <strong>grande taille</strong>, présentent quelques granulations et parfois des <strong>bâtonnets rouges azurophiles</strong> appelés <strong>corps d'Auer</strong>.</li><li>Pour les <strong>LAL</strong> : les blastes sont de <strong>petite/moyenne taille</strong>, avec un <strong>cytoplasme peu abondant</strong> et un <strong>noyau à contours irréguliers</strong> avec une chromatine claire.</li></ul>"},{"i":"3d99d827f2c3","n":315,"o":"315-2","u":"Définition","t":"Connaître les catégories de LA (hors classification)","q":"Quelles sont les caractéristiques de la forme particulière LAM3 (leucémie aiguë promyélocytaire) ?","a":"<p>La <strong>LAM3</strong> est sévère par la présence d'une <strong>CIVD quasi-constante</strong>, et est associée à une <strong>translocation t(15;17)</strong>. C'est une urgence thérapeutique traitée par <strong>ATRA</strong> (acide tout-trans rétinoïque).</p>"},{"i":"81043ad8b825","n":315,"o":"315-2","u":"Définition","t":"Connaître les catégories de LA (hors classification)","q":"Quelle est la particularité des LAL à chromosome Philadelphie ?","a":"<p>Ces <strong>LAL à chromosome Philadelphie</strong> sont généralement des <strong>LAL-B</strong> portant la <strong>translocation t(9;22)</strong>. Elles nécessitent un traitement par <strong>inhibiteur de tyrosine kinase</strong> et sont associées à un <strong>pronostic péjoratif</strong>.</p>"},{"i":"8781725ea917","n":315,"o":"315-2","u":"Définition","t":"Connaître les catégories de LA (hors classification)","q":"Quels marqueurs d'immunophénotypage sont typiques des leucémies aiguës myéloïdes (LAM) et des sous-types de leucémies aiguës lymphoblastiques (LAL-B, LAL-T) ?","a":"<ul><li>Pour les <strong>LAM</strong> : marqueurs <strong>CD13</strong>, <strong>CD33</strong>, <strong>CD34</strong>.</li><li>Pour les <strong>LAL-B</strong> (65 % des LAL) : marqueurs <strong>CD19</strong>, <strong>CD20</strong>, <strong>CD79a</strong>.</li><li>Pour les <strong>LAL-T</strong> (35 % des LAL) : marqueurs <strong>CD3</strong>, <strong>CD5</strong>.</li></ul>"},{"i":"af8aa5447688","n":315,"o":"315-2","u":"Définition","t":"Connaître les catégories de LA (hors classification)","q":"Quelles sont les particularités cliniques de la forme LAM5 (leucémie aiguë monoblastique) ?","a":"<p>La <strong>LAM5</strong> se caractérise par une présentation <strong>hyperleucocytaire</strong> et des <strong>atteintes extra-médullaires</strong> (méningées, cutanées, gingivales), avec un risque de <strong>leucostase</strong>.</p>"},{"i":"e1dc5a17fc3c","n":315,"o":"315-2","u":"Définition","t":"Connaître les catégories de LA (hors classification)","q":"Comment distingue-t-on les deux grandes catégories de leucémies aiguës (LAM et LAL) ?","a":"<p>La distinction entre leucémie aiguë myéloïde (LAM) et leucémie aiguë lymphoblastique (LAL) repose sur plusieurs critères d'analyse des blastes :</p><ul><li>La <strong>morphologie</strong>.</li><li>La <strong>cytochimie</strong>.</li><li>L'<strong>immunophénotype</strong>.</li></ul>"},{"i":"06ba41a1b69e","n":315,"o":"315-4","u":"Diagnostic positif","t":"Connaître les signes cliniques liés à l’insuffisance médullaire","q":"Quels signes cliniques de syndrome tumoral peuvent être associés à l'insuffisance médullaire dans les leucémies aiguës ?","a":"<p>Un syndrome tumoral peut s'y associer, surtout dans les Leucémies Aiguës Lymphoblastiques (LAL), par envahissement des organes lymphoïdes :</p><ul><li><strong>Adénopathies</strong>.</li><li><strong>Hépato-splénomégalie</strong>.</li><li><strong>Amygdalomégalie</strong>.</li></ul>"},{"i":"0b48425c763f","n":315,"o":"315-4","u":"Diagnostic positif","t":"Connaître les signes cliniques liés à l’insuffisance médullaire","q":"Quels sont les signes cliniques du syndrome hémorragique dans le contexte d'une leucémie aiguë ?","a":"<p>Le syndrome hémorragique, dû à la thrombopénie, se manifeste par des <strong>saignements cutanéo-muqueux</strong> :</p><ul><li><strong>Purpura</strong>.</li><li><strong>Ecchymoses</strong>.</li><li><strong>Gingivorragies</strong>.</li></ul><p>Une <strong>CIVD</strong> peut aggraver ce syndrome avec des saignements viscéraux ou profonds.</p>"},{"i":"24d1be94ffee","n":315,"o":"315-4","u":"Diagnostic positif","t":"Connaître les signes cliniques liés à l’insuffisance médullaire","q":"Quels sont les signes cliniques du syndrome infectieux dans le contexte d'une leucémie aiguë ?","a":"<p>Le syndrome infectieux, dû à la neutropénie, présente une clinique souvent pauvre mais peut inclure :</p><ul><li><strong>Fièvre</strong>.</li><li><strong>Angine ulcéro-nécrotique</strong>.</li><li><strong>Aphtose</strong>.</li><li><strong>Pneumopathie</strong>.</li><li><strong>Cellulites</strong>, notamment périnéales.</li></ul>"},{"i":"27a63e0f0a22","n":315,"o":"315-4","u":"Diagnostic positif","t":"Connaître les signes cliniques liés à l’insuffisance médullaire","q":"Comment l'insuffisance médullaire se manifeste-t-elle cliniquement dans les leucémies aiguës ?","a":"<p>L'insuffisance médullaire dans les leucémies aiguës se manifeste par une symptomatologie rapidement progressive associée à trois syndromes :</p><ul><li>Le syndrome anémique (liée à l'anémie).</li><li>Le syndrome hémorragique (lié à la thrombopénie).</li><li>Le syndrome infectieux (lié à la neutropénie).</li></ul>"},{"i":"48c1f96eeb39","n":315,"o":"315-4","u":"Diagnostic positif","t":"Connaître les signes cliniques liés à l’insuffisance médullaire","q":"Quels sont les signes cliniques du syndrome anémique dans le contexte d'une leucémie aiguë ?","a":"<p>Le syndrome anémique, dû à l'anémie, présente des signes cliniques d'installation rapide, souvent mal tolérés :</p><ul><li><strong>Asthénie</strong>.</li><li><strong>Dyspnée</strong>.</li><li><strong>Pâleur</strong>.</li><li><strong>Douleur thoracique</strong>.</li></ul>"},{"i":"3e59d3d70831","n":315,"o":"315-5","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques de gravité","q":"Quels sont les signes cliniques et biologiques d'une urgence liée à une cytopénie profonde dans le cadre d'une leucémie aiguë ?","a":"<p>Les signes d'urgence liés à une cytopénie profonde sont :</p><ul><li><strong>Anémie :</strong> Hémoglobine &lt; <strong>7 g/dL</strong> avec risque de syndrome coronarien aigu (SCA).</li><li><strong>Thrombopénie :</strong> Plaquettes &lt; <strong>20 G/L</strong> avec risque d'hémorragie rétinienne ou méningée.</li><li><strong>Neutropénie :</strong> Polynucléaires neutrophiles &lt; <strong>0,5 G/L</strong> avec risque de sepsis sévère à bacille à Gram négatif.</li></ul>"},{"i":"514897d798e5","n":315,"o":"315-5","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques de gravité","q":"Quels sont les éléments cliniques et biologiques définissant un syndrome de leucostase dans le contexte d'une leucémie aiguë ?","a":"<p>Le syndrome de leucostase est caractérisé par :</p><ul><li>Une <strong>hyperleucocytose &gt; 100 G/L</strong>.</li><li>Des atteintes capillaires, notamment <strong>pulmonaires</strong> et <strong>cérébrales</strong>.</li><li>Il est préférentiellement observé dans les <strong>LAM5</strong> (et LAM4).</li></ul>"},{"i":"5a9cc9da392f","n":315,"o":"315-5","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques de gravité","q":"Devant quelle triade clinique et biologique faut-il suspecter une leucémie aiguë myéloïde (LAM3) promyélocytaire et initier un traitement en urgence ?","a":"<p>Il faut suspecter une LAM3 promyélocytaire devant la triade suivante :</p><ul><li><strong>Insuffisance médullaire</strong> (cytopénies profondes).</li><li>Présence de <strong>blastes circulants</strong>.</li><li>Présence d'une <strong>CIVD</strong> (coagulation intravasculaire disséminée).</li></ul><p>Dans ce cas, il est impératif de débuter l'<strong>ATRA</strong> (acide tout-trans rétinoïque) sans attendre la confirmation cytogénétique de la t(15;17).</p>"},{"i":"5b978d0abd23","n":315,"o":"315-5","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques de gravité","q":"Dans le contexte d'une leucémie aiguë, quels sont les signes biologiques évocateurs d'un syndrome de lyse tumorale ?","a":"<p>Les signes biologiques clés d'un syndrome de lyse tumorale sont :</p><ul><li><strong>Hyperuricémie</strong>.</li><li><strong>Hyperkaliémie</strong>.</li><li><strong>Hyperphosphorémie</strong>.</li><li><strong>Hypocalcémie</strong>.</li><li>Augmentation très importante des <strong>LDH</strong> (lactate déshydrogénase).</li></ul>"},{"i":"16b224727237","n":315,"o":"315-6","u":"Diagnostic positif","t":"Savoir identifier les signes évocateurs du diagnostic de LA sur l’hémogramme","q":"Quelle est l'anomalie de la lignée plaquettaire fréquemment observée sur l'hémogramme d'une leucémie aiguë ?","a":"<p>La lignée plaquettaire est caractérisée par une <strong>thrombopénie</strong>, qui peut être sévère avec des plaquettes <strong>&lt; 10 G/L</strong>.</p>"},{"i":"192d82cb3e49","n":315,"o":"315-6","u":"Diagnostic positif","t":"Savoir identifier les signes évocateurs du diagnostic de LA sur l’hémogramme","q":"Quelle est l'anomalie de la lignée érythrocytaire fréquemment observée sur l'hémogramme d'une leucémie aiguë ?","a":"<p>L'hémogramme d'une leucémie aiguë révèle une <strong>anémie arégénérative</strong>, le plus souvent <strong>normocytaire</strong> ou modérément macrocytaire.</p>"},{"i":"565570bf0f3c","n":315,"o":"315-6","u":"Diagnostic positif","t":"Savoir identifier les signes évocateurs du diagnostic de LA sur l’hémogramme","q":"Comment la numération leucocytaire varie-t-elle sur l'hémogramme d'une leucémie aiguë ?","a":"<p>La numération leucocytaire est <strong>variable</strong> : elle peut correspondre à une <strong>leucopénie</strong> (formes leucopéniques) ou, à l'inverse, à une <strong>hyperleucocytose majeure</strong> (formes hyperleucocytaires).</p>"},{"i":"a45cf0c9d196","n":315,"o":"315-6","u":"Diagnostic positif","t":"Savoir identifier les signes évocateurs du diagnostic de LA sur l’hémogramme","q":"Quelle observation sur le frottis sanguin d'une leucémie aiguë doit alerter et justifie une relecture cytologique spécialisée ?","a":"<p>La présence de <strong>blastes circulants</strong> sur le frottis sanguin justifie une <strong>relecture cytologique spécialisée</strong>, car leur identification morphologique peut être difficile.</p>"},{"i":"bff9cb3cf32e","n":315,"o":"315-6","u":"Diagnostic positif","t":"Savoir identifier les signes évocateurs du diagnostic de LA sur l’hémogramme","q":"Quelle anomalie de la lignée granuleuse est quasi constante sur l'hémogramme d'une leucémie aiguë ?","a":"<p>Une <strong>neutropénie</strong> est presque constante, pouvant aller jusqu'à une <strong>agranulocytose</strong> d'emblée.</p>"},{"i":"e54830cdca93","n":315,"o":"315-6","u":"Diagnostic positif","t":"Savoir identifier les signes évocateurs du diagnostic de LA sur l’hémogramme","q":"Un hémogramme normal peut-il éliminer le diagnostic de leucémie aiguë ?","a":"<p>Non, un hémogramme normal n'élimine pas le diagnostic de leucémie aiguë, notamment chez l'<strong>enfant</strong>. Le <strong>myélogramme</strong> reste indispensable pour affirmer le diagnostic.</p>"},{"i":"1508c54c7630","n":315,"o":"315-8","u":"Epidémiologie","t":"Connaître les particularités épidémiologiques des LA de l’enfant","q":"Décrivez les pics d'incidence des LAL et des LAM chez l'enfant selon l'âge.","a":"<ul><li>Pour la <strong>LAL</strong> : un pic d'incidence entre <strong>2 et 5 ans</strong>, et un second pic à l'adolescence.</li><li>Pour la <strong>LAM</strong> : une incidence maximale chez le <strong>nourrisson</strong>, qui décroît jusqu'à 10 ans puis réaugmente.</li></ul>"},{"i":"55ea6f5de1a5","n":315,"o":"315-8","u":"Epidémiologie","t":"Connaître les particularités épidémiologiques des LA de l’enfant","q":"Chez l'enfant, quelle est la proportion de LAL et de LAM parmi les leucémies aiguës et quelle est leur incidence respective ?","a":"<ul><li>La <strong>LAL</strong> représente <strong>80 %</strong> des leucémies aiguës de l'enfant, avec environ <strong>400 nouveaux cas par an</strong>.</li><li>La <strong>LAM</strong> représente <strong>20 %</strong> des leucémies aiguës de l'enfant, avec environ <strong>70 nouveaux cas par an</strong>.</li></ul>"},{"i":"60b330016425","n":315,"o":"315-8","u":"Epidémiologie","t":"Connaître les particularités épidémiologiques des LA de l’enfant","q":"Comment les leucémies aiguës se positionnent-elles en termes de fréquence parmi les cancers pédiatriques ?","a":"<p>Les leucémies aiguës sont les <strong>cancers pédiatriques les plus fréquents</strong>, représentant <strong>un tiers</strong> de l'ensemble des cancers de l'enfant.</p>"},{"i":"7482056db37d","n":315,"o":"315-8","u":"Epidémiologie","t":"Connaître les particularités épidémiologiques des LA de l’enfant","q":"Quelle est la particularité de la répartition des types de leucémies aiguës chez l'enfant par rapport à l'adulte ?","a":"<p>Contrairement à l'adulte où la Leucémie Aiguë Myéloïde (LAM) domine, c'est la <strong>Leucémie Aiguë Lymphoblastique (LAL)</strong> qui prédomine largement chez l'enfant.</p>"},{"i":"a679e975c461","n":315,"o":"315-8","u":"Epidémiologie","t":"Connaître les particularités épidémiologiques des LA de l’enfant","q":"Quelles sont les particularités biologiques souvent retrouvées dans les LAL de l'enfant de 1 à 10 ans ?","a":"<p>Chez l'enfant de 1 à 10 ans, les LAL portent souvent une <strong>translocation ETV6-RUNX1</strong> ou une <strong>hyperdiploïdie</strong>. Ces altérations oncogéniques initiatrices sont rares à l'âge adulte.</p>"},{"i":"139126e4b5fc","n":315,"o":"315-9","u":"Diagnostic positif","t":"Connaître les circonstances cliniques et biologiques devant faire évoquer une LA chez l’enfant","q":"Quels sont les signes cliniques généraux d'une leucémie aiguë chez l'enfant ?","a":"<p>Les signes cliniques généraux d'une leucémie aiguë chez l'enfant sont ceux de l'adulte :</p><ul><li><strong>Insuffisance médullaire</strong> (anémie, thrombopénie, neutropénie)</li><li><strong>Syndrome tumoral</strong> (adénopathies, hépatosplénomégalie)</li></ul>"},{"i":"db4fe31593b2","n":315,"o":"315-9","u":"Diagnostic positif","t":"Connaître les circonstances cliniques et biologiques devant faire évoquer une LA chez l’enfant","q":"Quel est l'aspect de l'hémogramme en cas de leucémie aiguë chez l'enfant et quels sont les pièges diagnostiques ?","a":"<p>L'hémogramme est généralement anormal, mais peut être normal sans éliminer le diagnostic. Il peut montrer :</p><ul><li>Une forme <strong>hyperleucocytaire à blastose variable</strong>.</li><li>Une forme <strong>pancytopénique sans blaste</strong>.</li></ul><p>Les pièges diagnostiques incluent :</p><ul><li>Devant une <strong>boiterie</strong> ou des <strong>douleurs osseuses</strong> chez l'enfant, toujours demander une <strong>NFS</strong> pour éliminer une LA, même en l'absence d'autres symptômes évocateurs.</li><li>Ne pas confondre les <strong>blastes</strong> avec des <strong>lymphocytes hyperbasophiles</strong> (fréquents dans les infections virales en pédiatrie) ; une relecture cytologique est nécessaire en cas de doute.</li></ul>"},{"i":"f3a9218f388a","n":315,"o":"315-9","u":"Diagnostic positif","t":"Connaître les circonstances cliniques et biologiques devant faire évoquer une LA chez l’enfant","q":"Quelle est la durée d'évolution typique d'une leucémie aiguë (LA) chez l'enfant avant le diagnostic ?","a":"<p>Chez l'enfant, la leucémie aiguë évolue typiquement sur une période de <strong>2 à 3 semaines</strong> avant le diagnostic.</p>"},{"i":"f56d1914c6a4","n":315,"o":"315-9","u":"Diagnostic positif","t":"Connaître les circonstances cliniques et biologiques devant faire évoquer une LA chez l’enfant","q":"Quelles sont les atteintes cliniques spécifiques à la leucémie aiguë chez l'enfant ?","a":"<p>Les atteintes cliniques spécifiques à la leucémie aiguë chez l'enfant sont :</p><ul><li><strong>Gros testicule</strong> : augmentation de volume testiculaire, souvent site de rechute.</li><li><strong>Douleurs ostéoarticulaires, boiterie</strong> : l'enfant « ne veut plus monter les escaliers », « veut être porté », « ne joue plus ». On peut retrouver des <strong>bandes claires métaphysaires</strong> à la radiographie.</li><li><strong>Infiltrats extramédullaires</strong> (chloromes) : fréquents chez le nourrisson atteint de LAM, pouvant mimer une tumeur solide.</li></ul>"}]};